1	:root {
2	  --ink: #1d2230;
3	  --muted: #5f6675;
4	  --line: #e3e5ea;
5	  --accent: #1f5bd8;
6	  --error: #b3261e;
7	  --bg: #f6f7f9;
8	  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
9	  color: var(--ink);
10	}
11	* { box-sizing: border-box; }
12	body { margin: 0; background: var(--bg); }
13	.top { padding: 14px 20px; background: #fff; border-bottom: 1px solid var(--line); }
14	.brand { font-weight: 700; color: var(--ink); text-decoration: none; }
15	
16	.cart { max-width: 1080px; margin: 0 auto; padding: 20px; display: flex; flex-direction: column; gap: 24px; }
17	.items { flex: 1; min-width: 0; }
18	h1 { font-size: 1.5rem; margin: 0 0 12px; }
19	.lines { list-style: none; margin: 0; padding: 0; background: #fff; border: 1px solid var(--line); border-radius: 8px; }
20	.line { display: grid; grid-template-columns: 1fr auto auto auto; align-items: center; gap: 12px; padding: 14px 16px; border-top: 1px solid var(--line); }
21	.line:first-child { border-top: 0; }
22	.line-name { font-weight: 600; }
23	.sku { display: block; font-weight: 400; font-size: .8rem; color: var(--muted); }
24	.stepper { display: inline-flex; align-items: center; border: 1px solid var(--line); border-radius: 6px; }
25	.stepper button { width: 32px; height: 32px; border: 0; background: none; font-size: 1.1rem; cursor: pointer; }
26	.stepper button:disabled { color: #b8bcc6; cursor: default; }
27	.qty { min-width: 28px; text-align: center; }
28	.line-total { min-width: 88px; text-align: right; font-variant-numeric: tabular-nums; }
29	.remove { border: 0; background: none; color: var(--accent); cursor: pointer; }
30	.empty { padding: 32px; text-align: center; color: var(--muted); background: #fff; border: 1px dashed var(--line); border-radius: 8px; }
31	
32	.summary { min-width: 400px; background: #fff; border: 1px solid var(--line); border-radius: 8px; padding: 20px; align-self: flex-start; }
33	.summary h2 { font-size: 1.1rem; margin: 0 0 12px; }
34	.totals { margin: 0 0 16px; }
35	.totals div { display: flex; justify-content: space-between; padding: 6px 0; }
36	.totals dt { color: var(--muted); }
37	.totals dd { margin: 0; font-variant-numeric: tabular-nums; }
38	.totals .grand { border-top: 1px solid var(--line); margin-top: 6px; padding-top: 10px; font-weight: 700; }
39	.totals .grand dt { color: var(--ink); }
40	.promo label { display: block; font-size: .9rem; margin-bottom: 4px; }
41	.promo-row { display: flex; gap: 8px; }
42	.promo-row input { flex: 1; min-width: 0; padding: 8px; border: 1px solid var(--line); border-radius: 6px; }
43	.promo-row button { padding: 8px 14px; border: 1px solid var(--accent); background: #fff; color: var(--accent); border-radius: 6px; cursor: pointer; }
44	.error { color: var(--error); font-size: .9rem; margin: 6px 0 0; }
45	.checkout { display: block; margin-top: 16px; padding: 12px; text-align: center; background: var(--accent); color: #fff; border-radius: 6px; text-decoration: none; font-weight: 600; }
46	
47	@media (min-width: 769px) {
48	  .cart { flex-direction: row; align-items: flex-start; }
49	  .summary { width: 340px; min-width: 340px; }
50	}
