import { chromium } from 'playwright-core';
const browser = await chromium.launch();

// --- Money format on default page load (subtotal exceeds $1,000) ---
{
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.goto('http://127.0.0.1:4173/');
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  const subtotalText = await page.locator('#subtotal').textContent();
  const totalText = await page.locator('#total').textContent();
  console.log('TEST-MONEY: subtotal text =', JSON.stringify(subtotalText), ' total text =', JSON.stringify(totalText));
  await page.close();
}

// --- Promo: apply invalid code then valid code, check error clears ---
{
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.goto('http://127.0.0.1:4173/');
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await page.fill('#promo', 'NOPE');
  await page.click('#promo-form button[type="submit"]');
  const errAfterBad = await page.locator('#promo-error').isVisible();
  const errTextBad = await page.locator('#promo-error').textContent();
  console.log('TEST-PROMO: after invalid code, error visible=', errAfterBad, 'text=', JSON.stringify(errTextBad));

  await page.fill('#promo', 'SAVE10');
  await page.click('#promo-form button[type="submit"]');
  const errAfterGood = await page.locator('#promo-error').isVisible();
  const discountText = await page.locator('#discount').textContent();
  console.log('TEST-PROMO: after valid code, error still visible=', errAfterGood, 'discount=', discountText);
  await page.screenshot({ path: '/tmp/ticket88-evidence/promo-error-after-valid.png' });
  await page.close();
}

// --- Promo: discount should follow later quantity changes ---
{
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.goto('http://127.0.0.1:4173/');
  await page.evaluate(() => localStorage.clear());
